def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([1]), fmt([1, 1]), fmt([1, 2]), fmt([1, 2, 3]), fmt([5] * 7),
             fmt([1, 2, 1, 2, 1, 2, 3, 3, 3]), fmt([7, 1, 2, 3, 3, 4, 5, 5, 5]),
             fmt([1, 2, 3, 2, 2]), fmt([4, 4, 9, 9, 4, 4, 9, 1, 1, 1, 1])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for k in (2, 3, 5):
            tests.append(fmt([rng.randint(1, k) for _ in range(n)]))
    N = 10**5
    tests.append(fmt([1, 2] * (N // 2)))
    tests.append(fmt([rng.randint(1, 2) for _ in range(N)]))
    tests.append(fmt([rng.randint(1, 3) for _ in range(N)]))
    a = []
    while len(a) < N:
        t = rng.randint(1, 10**9)
        a += [t] * rng.randint(1, 3000)
    tests.append(fmt(a[:N]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(N)]))
    return tests
